const std=@import("std");const s=@import("support.zig");const m=@import("model.zig");const l=@import("ledger.zig");
fn less(_:void,x:[]const u8,y:[]const u8)bool{return std.mem.lessThan(u8,x,y);}pub fn run(a:std.mem.Allocator,r:s.V)!s.V{try m.validate(r);var stock=std.StringHashMap(i64).init(a);for((try s.array(s.get(r,"stock"),32)))|x|try stock.put(try s.id(s.get(x,"id")),try s.integer(s.get(x,"quantity"),0,1000000));var active=std.StringHashMap(m.Reservation).init(a);var results=s.list(a);for((try s.array(s.get(r,"operations"),128)))|op|{const token=try s.id(s.get(op,"token"));const status=if(std.mem.eql(u8,s.get(op,"op").string,"reserve"))try l.reserve(&stock,&active,token,try s.id(s.get(op,"id")),try s.integer(s.get(op,"quantity"),1,1000000))else try l.release(&stock,&active,token);try results.array.append(.{.string=status});}var keys:std.ArrayList([]const u8)=.empty;var it=stock.keyIterator();while(it.next())|k|try keys.append(a,k.*);std.mem.sort([]const u8,keys.items,{},less);var available=s.list(a);for(keys.items)|k|{var row=s.object();try s.put(a,&row,"id",.{.string=k});try s.put(a,&row,"quantity",.{.integer=stock.get(k).?});try available.array.append(row);}keys.clearRetainingCapacity();var ai=active.keyIterator();while(ai.next())|k|try keys.append(a,k.*);std.mem.sort([]const u8,keys.items,{},less);var names=s.list(a);for(keys.items)|k|try names.array.append(.{.string=k});var out=s.object();try s.put(a,&out,"results",results);try s.put(a,&out,"available",available);try s.put(a,&out,"active",names);return out;}
